// Get the COMPLETE input data
const fullInput = $input.first()?.json || {};
const pdfTextt = fullInput.text || fullInput.data?.text || 'No PDF text extracted';
// Replace PDF text with the provided meeting details
const pdfText = `Project: Smart Meeting Assistant Agent (n8n)
Objective: Finalize the workflow integration for Telegram and Google Calendar
Discussion Points:
1. Review PDF extraction accuracy
2. Test LLM prompt formatting
3. Validate calendar invite automation
4. Verify email notifications
Participants: eng.mohamedareda@gmail.com, sa6056420@gmail.com
Preferred Date: 2025-05-2
Time: 9 pm
Duration: 10 minutes`;

// Get the user prompt (checking all possible message locations)
const userPrompt = fullInput.message?.text || 
                  fullInput.message?.caption || 
                  fullInput.llm_input || 
                  '';

return [{
  json: {
    llm_input: `User request: ${userPrompt}\n\nExtracted PDF content:\n${pdfText}`
    ,pdf:pdfTextt
  }
}];

// Get the input data
const input = $input.first()?.json || {};

// Extract meeting text from any location
const meetingText = input.text || input.data?.text || input.llm_input || '';

// Initialize result with proper Google Calendar format
const result = {
  start: {
    dateTime: '2025-05-02T21:00:00',
    timeZone: 'Africa/Cairo'
  },
  end: {
    dateTime: '2025-05-02T21:10:00',
    timeZone: 'Africa/Cairo'
  },
  summary: 'Smart Meeting Assistant Agent (n8n)',
  description: 'Finalize the workflow integration for Telegram and Google Calendar',
  attendees: [
    { email: 'eng.mohamedareda@gmail.com' },
    { email: 'sa6056420@gmail.com' }
  ]
};

// Parse meeting text if available
if (meetingText.includes('Project:')) {
  const lines = meetingText.split('\n').map(line => line.trim()).filter(line => line);

  const dateStr = lines.find(l => l.startsWith('Preferred Date:'))?.split(': ')[1] || '2025-05-02';
  const timeStr = lines.find(l => l.startsWith('Time:'))?.split(': ')[1] || '21:00';
  const duration = parseInt(lines.find(l => l.startsWith('Duration:'))?.split(': ')[1]) || 10;

  // Convert to proper ISO format
  const startDate = new Date(`${dateStr}T${timeStr}:00Z`);
  const endDate = new Date(startDate.getTime() + duration * 60000);

  result.start.dateTime = startDate.toISOString();
  result.end.dateTime = endDate.toISOString();
  result.summary = lines.find(l => l.startsWith('Project:'))?.split(': ')[1] || result.summary;
  result.description = lines.find(l => l.startsWith('Objective:'))?.split(': ')[1] || result.description;

  const participants = lines.find(l => l.startsWith('Participants:'))?.split(': ')[1].split(',');
  if (participants) {
    result.attendees = participants.map(email => ({ email: email.trim() }));
  }
}

return [{
  json: result
}];

// Get meeting details from previous node
const meetingData = $input.first().json;

// Extract core meeting information with error handling
const meetingName = meetingData?.summary || "Smart Meeting Assistant Agent Discussion";
const details = meetingData?.description || "Workflow integration finalization";
const participants = meetingData?.attendees?.map(attendee => {
  // Extract name from email before @
  const namePart = attendee.email.split('@')[0].replace(/[^a-zA-Z]/g, ' ');
  return namePart.trim().split(' ')[0] || 'Participant';
}) || ["Mohamed", "SA"];

// Get formatted date from calendar event
const meetingDate = meetingData?.start?.dateTime ?
  new Date(meetingData.start.dateTime).toLocaleString('en-EG', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Africa/Cairo'
  }) : "May 2nd, 2025 at 9:00 PM EET";

// Generate structured transcript
const transcript = `
Meeting: ${meetingName}
Date: ${meetingDate}
Participants: ${participants.join(', ')}
Agenda: ${details}

[00:00] Moderator: Welcome everyone. Let's begin our discussion about ${meetingName}.
[00:05] ${participants[0]}: I recommend we start by reviewing the PDF extraction accuracy.
[00:10] ${participants[1]}: Agreed. We should also verify the calendar invite automation.
[00:15] Moderator: Good points. Let's address these items in order:
          1. ${details.split('.')[0]}
          2. Email notification validation`;

return [{ 
  json: { 
    transcript: transcript.trim(),
    originalData: meetingData // Maintain reference to source data
  } 
}];
